const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Sakha Republic approximate bounds
  const sakha = ee.Geometry.Polygon([
    [105, 50], [150, 50], [150, 75], [105, 75], [105, 50]
  ]);

  // 2. Data Acquisition - MODIS Burned Area
  const burned2015 = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterDate('2015-01-01', '2015-12-31')
    .filterBounds(sakha);

  const burned2021 = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterDate('2021-01-01', '2021-12-31')
    .filterBounds(sakha);

  // Check collection sizes
  const size2015 = burned2015.size().getInfo();
  const size2021 = burned2021.size().getInfo();

  console.log(`2015 Images: ${size2015}, 2021 Images: ${size2021}`);

  if (size2015 === 0 || size2021 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create annual burned area composites
  const burnedMask2015 = burned2015.select('BurnDate').max().gt(0);
  const burnedMask2021 = burned2021.select('BurnDate').max().gt(0);

  // Count burned pixels
  const count2015 = burnedMask2015.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sakha,
    scale: 1000,
    maxPixels: 1e9
  }).get('BurnDate').getInfo();

  const count2021 = burnedMask2021.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sakha,
    scale: 1000,
    maxPixels: 1e9
  }).get('BurnDate').getInfo();

  console.log(`2015 Burned Pixels: ${Math.round(count2015)}`);
  console.log(`2021 Burned Pixels: ${Math.round(count2021)}`);

  // 4. Validation & Final Answer
  if (count2015 === null || count2021 === null || 
      isNaN(count2015) || isNaN(count2021)) {
    console.log("<answer>C3</answer>");
  } else if (count2015 === 0 && count2021 === 0) {
    console.log("<answer>C2</answer>");
  } else if (count2015 > count2021) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
